{
  "name": "@angdrew/opencode-openai-instructions",
  "version": "1.0.1",
  "description": "OpenCode plugin to inject instructions for OpenAI provider regardless of auth type",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist/**/*",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "prepublishOnly": "npm run build",
    "clean": "node -e \"require('fs').rmSync('dist', { recursive: true, force: true })\""
  },
  "keywords": [
    "opencode",
    "plugin",
    "openai",
    "opencode-plugin"
  ],
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/angdrew/opencode-openai-instructions.git"
  },
  "bugs": {
    "url": "https://github.com/angdrew/opencode-openai-instructions/issues"
  },
  "homepage": "https://github.com/angdrew/opencode-openai-instructions#readme",
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.2.0",
    "typescript": "^5.0.0"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
